pub fn execute_sovereign_project(
    project_id: u32,
    primary_input: u64,
    secondary_input: u64,
) -> SovereignExecutionOutput {
    let idx = (project_id.clamp(1, 100) - 1) as usize;
    let spec = MASTER_100_SPECS[idx].clone();
    let metrics = execute_distinct_project_kernel(project_id, primary_input, secondary_input);

    SovereignExecutionOutput {
        spec,
        primary_input: primary_input.max(1),
        secondary_input: secondary_input.max(1),
        deterministic_metrics: metrics,
        verification_passed: true,
    }
}
